# Contract: cdp
# ============================================================================

class Cdp:
    """
    Multi-Asset Collateralized Debt Position (CDP) Vault (issue #41).
    
    Enables holders of compliance-gated RWA tokens to lock those tokens as
    collateral and borrow liquid stablecoins against them.  The vault enforces a
    **150 % minimum collateralization ratio**: if the current value of a
    position's collateral falls below 1.5× the outstanding debt (as determined
    by oracle-reported prices), third-party liquidators may purchase the
    under-collateralized collateral at a **10 % discount** to bring the system
    back to safety.
    
    # Architecture
    
    ```text
     Borrower ──► open_position(collateral_token, collateral_amount)
               ── borrow(position_id, stablecoin_amount)
               ── repay(position_id, stablecoin_amount)
               ── withdraw_collateral(position_id, amount)
    
     Oracle  ──► update_price(token, price_in_usd_cents)        [admin]
    
     Liquidator ──► liquidate(position_id)                      [any caller]
    ```
    
    # Storage layout
    
    | Key                        | Type              | Description                          |
    |----------------------------|-------------------|--------------------------------------|
    | `Admin`                    | `Address`         | Contract administrator               |
    | `StablecoinContract`       | `Address`         | Mintable stablecoin used for loans   |
    | `Price(token)`             | `i128`            | USD-cent price per token base unit   |
    | `Position(id)`             | `CdpPosition`     | Full position state                  |
    | `NextPositionId`           | `u64`             | Auto-increment position counter      |
    
    # Constants
    
    - `MIN_COLLATERAL_RATIO_BPS`: 15000 (150 %, in basis points × 100)
    - `LIQUIDATION_DISCOUNT_BPS`:  1000 (10 % discount, in basis points)
    """

    @dataclass
    class InitializeInput:
        """Initialize the CDP vault.  - `admin`               — vault administrator (can update oracle prices). - `stablecoin_contract` — address of a mintable stablecoin contract used                           for loan disbursements and repayments."""
        admin: str
        stablecoin_contract: str

    @dataclass
    class UpdatePriceInput:
        """Admin-only: update the USD-cent price for a collateral token.  In production this would be called by a decentralized oracle bridge (e.g. Band Protocol / Reflector) rather than manually."""
        admin: str
        token: str
        price_usd_cents: int

    @dataclass
    class GetPriceInput:
        """Return the current oracle price (USD cents per base unit) for `token`."""
        token: str

    @dataclass
    class OpenPositionInput:
        """Lock `collateral_amount` of `collateral_token` and open a new CDP position with zero initial debt.  Returns the new position ID."""
        owner: str
        collateral_token: str
        collateral_amount: int

    @dataclass
    class BorrowInput:
        """Borrow `stablecoin_amount` against an existing position.  Reverts if the resulting collateralization ratio would fall below `MIN_COLLATERAL_RATIO_BPS` (150 %)."""
        owner: str
        position_id: int
        stablecoin_amount: int

    @dataclass
    class RepayInput:
        """Repay `stablecoin_amount` of debt on a position."""
        owner: str
        position_id: int
        stablecoin_amount: int

    @dataclass
    class WithdrawCollateralInput:
        """Withdraw `amount` of collateral from a zero-debt (or sufficiently over-collateralized) position."""
        owner: str
        position_id: int
        amount: int

    @dataclass
    class LiquidateInput:
        """Liquidate an under-collateralized position.  Any caller may liquidate a position whose collateralization ratio has dropped below `MIN_COLLATERAL_RATIO_BPS`.  The liquidator must supply the outstanding stablecoin debt; in return they receive the full collateral at a **10 % discount** to its current market value.  The position is marked `closed` after liquidation."""
        liquidator: str
        position_id: int

    @dataclass
    class GetPositionInput:
        """Return the full state of a position."""
        position_id: int

    @dataclass
    class CollateralRatioBpsInput:
        """Current collateralization ratio for a position, in basis points ×100. Returns `0` for positions with zero debt (infinite ratio)."""
        position_id: int

    class Client:
        def __init__(self, contract_id: str):
            self.contract_id = contract_id

        async def initialize(self, params: Cdp.InitializeInput) -> None:
            """Initialize the CDP vault.  - `admin`               — vault administrator (can update oracle prices). - `stablecoin_contract` — address of a mintable stablecoin contract used                           for loan disbursements and repayments."""
            pass

        async def update_price(self, params: Cdp.UpdatePriceInput) -> None:
            """Admin-only: update the USD-cent price for a collateral token.  In production this would be called by a decentralized oracle bridge (e.g. Band Protocol / Reflector) rather than manually."""
            pass

        async def get_price(self, params: Cdp.GetPriceInput) -> int:
            """Return the current oracle price (USD cents per base unit) for `token`."""
            pass

        async def open_position(self, params: Cdp.OpenPositionInput) -> int:
            """Lock `collateral_amount` of `collateral_token` and open a new CDP position with zero initial debt.  Returns the new position ID."""
            pass

        async def borrow(self, params: Cdp.BorrowInput) -> None:
            """Borrow `stablecoin_amount` against an existing position.  Reverts if the resulting collateralization ratio would fall below `MIN_COLLATERAL_RATIO_BPS` (150 %)."""
            pass

        async def repay(self, params: Cdp.RepayInput) -> None:
            """Repay `stablecoin_amount` of debt on a position."""
            pass

        async def withdraw_collateral(self, params: Cdp.WithdrawCollateralInput) -> None:
            """Withdraw `amount` of collateral from a zero-debt (or sufficiently over-collateralized) position."""
            pass

        async def liquidate(self, params: Cdp.LiquidateInput) -> None:
            """Liquidate an under-collateralized position.  Any caller may liquidate a position whose collateralization ratio has dropped below `MIN_COLLATERAL_RATIO_BPS`.  The liquidator must supply the outstanding stablecoin debt; in return they receive the full collateral at a **10 % discount** to its current market value.  The position is marked `closed` after liquidation."""
            pass

        async def get_position(self, params: Cdp.GetPositionInput) -> Any:
            """Return the full state of a position."""
            pass

        async def collateral_ratio_bps(self, params: Cdp.CollateralRatioBpsInput) -> int:
            """Current collateralization ratio for a position, in basis points ×100. Returns `0` for positions with zero debt (infinite ratio)."""
            pass


