# Contract: escrow
# ============================================================================

class Escrow:
    """
    Issue #86 - multi-party threshold escrow (buyer / seller / inspector) with
    ledger-window timeouts.
    
    Flow: the buyer funds the escrow in `create_escrow`. Each party calls
    `approve_release`; once `threshold` distinct approvals are recorded AND the
    inspector has approved, the funds are paid to the seller. If the inspector
    has not approved by `inspection_deadline` (current ledger + a configurable
    window), anyone may call `refund` and the funds return to the buyer.
    Buyer or seller may `raise_dispute`, which freezes release; the inspector
    settles it with `resolve_dispute`, and if nobody does within
    `dispute_window` ledgers `refund` returns the funds to the buyer.
    """

    @dataclass
    class CreateEscrowInput:
        """Create and fund an escrow. `inspection_window` and `dispute_window` are ledger counts. Returns the escrow id."""
        buyer: str
        seller: str
        inspector: str
        token: str
        amount: int
        threshold: int
        inspection_window: int
        dispute_window: int

    @dataclass
    class ApproveReleaseInput:
        """Record `signer`'s approval; releases to the seller when the threshold is met and the inspector has signed. After the inspection deadline no further approvals are accepted unless the inspector already approved."""
        id: int
        signer: str

    @dataclass
    class RaiseDisputeInput:
        """Buyer or seller freezes release and starts the dispute window."""
        id: int
        party: str

    @dataclass
    class ResolveDisputeInput:
        """Inspector settles a dispute (before the dispute window lapses)."""
        id: int
        inspector: str
        release_to_seller: bool

    @dataclass
    class RefundInput:
        """Return funds to the buyer. Permissionless, but only valid once a deadline has lapsed: the inspection deadline with no inspector approval, or the dispute deadline of an unresolved dispute."""
        id: int

    @dataclass
    class GetEscrowInput:
        """Invokes `get_escrow` on escrow."""
        id: int

    class Client:
        def __init__(self, contract_id: str):
            self.contract_id = contract_id

        async def create_escrow(self, params: Escrow.CreateEscrowInput) -> int:
            """Create and fund an escrow. `inspection_window` and `dispute_window` are ledger counts. Returns the escrow id."""
            pass

        async def approve_release(self, params: Escrow.ApproveReleaseInput) -> None:
            """Record `signer`'s approval; releases to the seller when the threshold is met and the inspector has signed. After the inspection deadline no further approvals are accepted unless the inspector already approved."""
            pass

        async def raise_dispute(self, params: Escrow.RaiseDisputeInput) -> None:
            """Buyer or seller freezes release and starts the dispute window."""
            pass

        async def resolve_dispute(self, params: Escrow.ResolveDisputeInput) -> None:
            """Inspector settles a dispute (before the dispute window lapses)."""
            pass

        async def refund(self, params: Escrow.RefundInput) -> None:
            """Return funds to the buyer. Permissionless, but only valid once a deadline has lapsed: the inspection deadline with no inspector approval, or the dispute deadline of an unresolved dispute."""
            pass

        async def get_escrow(self, params: Escrow.GetEscrowInput) -> Any:
            """Invokes `get_escrow` on escrow."""
            pass


